import { useState, useEffect, useRef, useCallback } from "react";

// ============================================================
// TYPE DEFINITIONS
// ============================================================

interface Vector2D {
  x: number;
  y: number;
}

interface PendulumState {
  angle: number;
  angularVelocity: number;
  angularAcceleration: number;
  length: number;
  mass: number;
  tension: number;
  velocity: Vector2D;
  position: Vector2D;
  pivotPosition: Vector2D;
  isFlying: boolean;
  flightTime: number;
  attachedObjectMass: number;
  collisionVelocity: Vector2D;
}

interface FormulaData {
  formula: string;
  title: string;
  context: string;
  variables: Record<string, string>;
}

interface OverlayBlock {
  type:
    | "definition"
    | "formula"
    | "table"
    | "note"
    | "summary"
    | "application"
    | "characteristics";
  title: string;
  content?: string;
  formulaData?: FormulaData;
  tableData?: { headers: string[]; rows: string[][] };
  highlight?: boolean;
}

// ============================================================
// PHYSICS ENGINE
// ============================================================

const G = 9.81;
const RAD = Math.PI / 180;

function computePendulumPhysics(state: PendulumState): PendulumState {
  const { angle, angularVelocity, length, mass, attachedObjectMass } = state;
  const totalMass = mass + attachedObjectMass;
  const alpha = -(G / length) * Math.sin(angle);
  const omega = angularVelocity + alpha * 0.016;
  const theta = angle + omega * 0.016;
  const v = omega * length;
  const vx = v * Math.cos(theta);
  const vy = v * Math.sin(theta);
  const tension = totalMass * ((v * v) / length + G * Math.cos(theta));
  const px =
    state.pivotPosition.x + length * Math.sin(theta) * 120;
  const py =
    state.pivotPosition.y + length * Math.cos(theta) * 120;
  return {
    ...state,
    angle: theta,
    angularVelocity: omega,
    angularAcceleration: alpha,
    tension,
    velocity: { x: vx, y: vy },
    position: { x: px, y: py },
  };
}

